<script>import{signIn}from'../logic/auth.js';import{t}from'../logic/i18n.js';let{lang='fa'}=$props();let username=$state('');let password=$state('');let error=$state('');let loading=$state(false);async function handleLogin(e){e.preventDefault();error='';loading=true;try{const result=await signIn(username,password);if(result.error){error=result.error;loading=false;return}window.location.hash='#/home';window.location.reload()}catch(err){loading=false;error=t(lang,'loginFailed')}}</script><div class="lp"><div class="lc"><div class="ll"><span class="li2">◆</span><h1>{t(lang,'siteTitle')}</h1></div><p class="ls">{t(lang,'loginTitle')}</p><form class="lf" onsubmit={handleLogin}><div class="fg"><label class="fl" for="login-user">{t(lang,'username')}</label><input id="login-user" type="text" class="fi" autocomplete="username" bind:value={username} required dir="ltr"/></div><div class="fg"><label class="fl" for="login-pass">{t(lang,'password')}</label><input id="login-pass" type="password" class="fi" autocomplete="current-password" placeholder="••••••••" bind:value={password} required dir="ltr"/></div>{#if error}<div class="fe"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg><span>{error}</span></div>{/if}<button type="submit" class="fb" disabled={loading}>{#if loading}<span class="sp"></span>{t(lang,'loggingIn')}{:else}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18"><path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><polyline points="10 17 15 12 10 7"/><line x1="15" y1="12" x2="3" y2="12"/></svg>{t(lang,'login')}{/if}</button></form><p class="lft"><a href="#/home">{t(lang,'backToHome')}</a></p></div></div><style>.lp{display:flex;align-items:center;justify-content:center;height:100%;padding:clamp(0.75rem,2vw,1.5rem) clamp(0.5rem,2vw,1rem);overflow:hidden}.lc{width:100%;max-width:min(380px,calc(100vw - 2rem));background:var(--color-bg-primary);border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:clamp(1.25rem,3vw,2.25rem) clamp(1rem,3vw,1.75rem);box-shadow:var(--shadow-lg);animation:fu 350ms ease;max-height:100%;overflow-y:auto}@keyframes fu{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}.ll{display:flex;align-items:center;justify-content:center;gap:0.5rem;margin-bottom:0.25rem}.li2{font-size:clamp(1.75rem,5vw,2.5rem);color:var(--color-accent)}.ll h1{font-size:var(--font-size-xl);color:var(--color-accent);margin:0;line-height:1.2}.ls{text-align:center;color:var(--color-text-muted);font-size:var(--font-size-sm);margin-bottom:clamp(1rem,3vw,1.75rem)}.fg{margin-bottom:0.85rem}.fl{display:block;font-size:var(--font-size-sm);font-weight:600;color:var(--color-text-secondary);margin-bottom:0.3rem}.fi{width:100%;padding:0.55rem 0.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md);background:var(--color-bg-secondary);color:var(--color-text-primary);font-family:var(--font-body);font-size:var(--font-size-base);transition:border var(--transition-fast),box-shadow var(--transition-fast);outline:none;box-sizing:border-box}.fi:focus{border-color:var(--color-accent);box-shadow:0 0 0 3px var(--color-accent-bg)}.fe{display:flex;align-items:flex-start;gap:0.5rem;padding:0.6rem 0.75rem;background:#fef2f2;border:1px solid #fecaca;border-radius:var(--radius-md);color:#dc2626;font-size:var(--font-size-sm);margin-bottom:1rem;line-height:1.4}:global([data-theme="dark"]) .fe{background:#450a0a;border-color:#7f1d1d;color:#fca5a5}.fe svg{flex-shrink:0;margin-top:1px}.fb{width:100%;padding:0.65rem;border:none;border-radius:var(--radius-md);background:var(--color-accent);color:var(--color-accent-text);font-family:var(--font-body);font-size:var(--font-size-base);font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:0.5rem;transition:background var(--transition-fast)}.fb:hover:not(:disabled){background:var(--color-accent-dark)}.fb:disabled{opacity:0.65;cursor:not-allowed}.sp{width:18px;height:18px;border:2px solid rgba(255,255,255,0.3);border-top-color:#fff;border-radius:50%;animation:spi 0.6s linear infinite}@keyframes spi{to{transform:rotate(360deg)}}.lft{text-align:center;margin-top:clamp(0.75rem,2vw,1.25rem);font-size:var(--font-size-sm)}.lft a{color:var(--color-link)}</style>